def set_left_most_unset_bit(n):
    # If the number is zero, return 1 as it's the only unset bit.
    if n == 0:
        return 1
    # Find the position of the leftmost unset bit.
    pos = -1
    while n > 0:
        pos += 1
        if n & 1 == 0:
            break
        n >>= 1

    # Set the leftmost unset bit and return the number.
    return n | (1 << pos)
